INSERT INTO "public"."enquiries" ("id", "agencyId", "customerId", "enquiryNumber", "title", "destination", "origin", "startDate", "endDate", "adults", "children", "infants", "budget", "budgetType", "currency", "hotelCategory", "mealPlan", "vehiclePreference", "transportRequired", "source", "priority", "status", "specialRequirements", "notes", "internalNotes", "assignedTo", "nextFollowUpAt", "convertedTripId", "convertedQuotationId", "lostReason", "closedAt", "archivedAt", "createdAt", "updatedAt", "lostExplanation", "assignedToUserId") VALUES ('cmvm32kzd000if8tqnmv409wm', 'cmu2g9rgq0000swtqbr5aie7x', 'cmvm2066r000bf8tqk9n3c0w2', 'ENQ-2026-00006', 'Shimla and Manali Trip - Meena Patel', 'Shimla and Manali', 'baroda', '2026-11-03T00:00:00.000Z', '2026-11-10T00:00:00.000Z', 10, 0, 0, '"79998"'::jsonb, 'per_person', 'INR', '3 Star', 'AP (All Meals)', 'Tempo Traveller', TRUE, 'INSTAGRAM', 'URGENT', 'NEW', 'Motorized vehicles are strictly banned on the central Mall Roads of both Shimla and Manali. Travelers must be prepared to walk from the designated vehicle drop-off points to their hotels', NULL, 'Room heating is not standard across all Himachal properties. For travel dates falling between November and March, the hotel voucher must explicitly state', NULL, '2026-10-28T00:00:00.000Z', NULL, NULL, NULL, NULL, NULL, '2026-10-24T07:34:37.753Z', '2026-10-24T07:34:37.753Z', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "public"."enquiries" ("id", "agencyId", "customerId", "enquiryNumber", "title", "destination", "origin", "startDate", "endDate", "adults", "children", "infants", "budget", "budgetType", "currency", "hotelCategory", "mealPlan", "vehiclePreference", "transportRequired", "source", "priority", "status", "specialRequirements", "notes", "internalNotes", "assignedTo", "nextFollowUpAt", "convertedTripId", "convertedQuotationId", "lostReason", "closedAt", "archivedAt", "createdAt", "updatedAt", "lostExplanation", "assignedToUserId") VALUES ('cmvm35bth000nf8tqtstbxywi', 'cmu2g9rgq0000swtqbr5aie7x', 'cmvm1xhb2000af8tqid9rok79', 'ENQ-2026-00007', 'Gujrat Trip - Pratik patel', 'Gujrat', 'Panjab', '2026-11-09T00:00:00.000Z', '2026-11-16T00:00:00.000Z', 14, 6, 0, '"115000"'::jsonb, 'per_person', 'INR', '3 Star', 'MAP', 'Tempo Traveller', TRUE, 'WHATSAPP', 'MEDIUM', 'NEW', 'The culinary landscape across Gujarat is overwhelmingly vegetarian. While premium resorts offer international selections, local meals are traditional, multi-course vegetarian menus (Gujarati Thali) that carry a distinctively sweet flavor prof', NULL, 'ion safari slots at Gir National Park are highly restricted and open 90 days in advance. Original government-issued photo IDs used during booking must be physically carried by each traveler to the forest checkpoint.', NULL, '2026-11-02T00:00:00.000Z', NULL, NULL, NULL, NULL, NULL, '2026-10-24T07:36:45.845Z', '2026-10-24T07:36:45.845Z', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "public"."enquiries" ("id", "agencyId", "customerId", "enquiryNumber", "title", "destination", "origin", "startDate", "endDate", "adults", "children", "infants", "budget", "budgetType", "currency", "hotelCategory", "mealPlan", "vehiclePreference", "transportRequired", "source", "priority", "status", "specialRequirements", "notes", "internalNotes", "assignedTo", "nextFollowUpAt", "convertedTripId", "convertedQuotationId", "lostReason", "closedAt", "archivedAt", "createdAt", "updatedAt", "lostExplanation", "assignedToUserId") VALUES ('cmvm38bcl000sf8tqeobtj2ai', 'cmu2g9rgq0000swtqbr5aie7x', 'cmvm1u4690009f8tqr5eh5v5n', 'ENQ-2026-00008', 'Kerala Trip - Mohit Patel', 'Kerala', 'Surat', '2026-11-16T00:00:00.000Z', '2026-11-23T00:00:00.000Z', 10, 0, 0, '"500000"'::jsonb, 'total', 'INR', 'Luxury Resort', 'MAP (Breakfast + Dinner)', 'Tempo Traveller', TRUE, 'PHONE', 'URGENT', 'NEW', 'While Kerala is famous for Ayurvedic massages, guests should only use wellness centers attached to approved 4/5-star resorts or those bearing the official government "Green Leaf" or "Olive Leaf" certification to ensure authentic, hygienic treatments.', NULL, '• Standard houseboat pricing only includes bedroom air conditioning operational from 9:00 PM to 6:00 AM. If the client profile demands "Premium Premium full-time AC" (including the lounge/dining space during day cruising), this must be manually requested and supplemented on the B2B voucher before dispatch.', NULL, '2026-11-09T00:00:00.000Z', NULL, NULL, NULL, NULL, NULL, '2026-10-24T07:39:05.205Z', '2026-10-24T07:39:05.205Z', NULL, NULL) ON CONFLICT DO NOTHING;
